    "C": """not ((not (not not (((not (not (not not (not not not (not (not not (not not not (4 * 9 > 6) and not not (The capital of Jordan is Beirut.)) or not not not (-3 * 7 is less than or equal to -6)) or (-9 * 4 + -3 * 2 <= 10 * 1)) and not not (1 * 4 + 2 * 1 is greater than 8 * -7)) or not not not (max(7, -4, -2, 1) - min(7, -4, -2, 1) is greater than 8)) and (2 * 2 <= -5)) and (6 * -8 > 3)) or (The capital of Belarus is Minsk.)) or (10 * 6 + 9 * 8 is greater than -2 * 10)) or not not not (-4 * 5 is less than or equal to -3)) or (max(-10, 1, -3, -4) - min(-10, 1, -3, -4) <= 8)) or (The capital of Afghanistan is Kabul.)) and (1 - (7 / -7) is greater than -10)""",
    "D": """not ((not (not (True) and (The capital of Colombia is Bogota.)) and (not not not (True) and not not (The capital of Afghanistan is Kabul.))) or (not (not (-8 * -7 + 5 * -10 is greater than 4 * -2) or (9 * 1 + -6 * -9 is less than or equal to -10 * 1)) and (not not (-8 * -7 + -8 * -1 is greater than -1 * 1) or not not not (The capital of Denmark is Copenhagen.)))) and (not not not (not not not (not not (The capital of Iran is Isfahan.) or not not not (The capital of Afghanistan is Kandahar.)) and not not (not (The capital of Afghanistan is Kabul.) or (5 - (-6 / 4) <= 6))) and not not (not (not not (True) or not not not (1 - (6 / -1) is greater than -6)) or (not not (-8 - (-3 / -6) > 3) or not not not (-4 * 1 + -5 * 3 is greater than -6 * 10))))""",
    "E": """not not not (not not ((not (not (not not (not (not (not not not (-1 - (-3 / -9) > 5) and not not (The capital of Nepal is Pokhara.)) or (-10 * -8 + 5 * -2 is less than or equal to -3 * 8)) or (5 * 3 + -9 * 9 <= 2 * -3)) or not not not (4 * -10 + -3 * 1 <= -9 * 1)) and (5 * -9 + -5 * 10 > -4 * -6)) and (True)) and (The capital of India is New Delhi.)) or not not not (max(-2, 4, -9, -8) - min(-2, 4, -9, -8) <= 7)) and not not (True)""",
}

capitals = {
    "Colombia": "Bogota",
    "Turkey": "Ankara",
    "Canada": "Ottawa",
    "Jordan": "Amman",
    "Belarus": "Minsk",
    "Afghanistan": "Kabul",
    "Denmark": "Copenhagen",
    "Iran": "Tehran",
    "Nepal": "Kathmandu",
    "India": "New Delhi",
}

fact_values = {}


def substitute_fact(match):
    country, city = match.groups()
    value = capitals[country] == city
    fact_values[country + ": " + city] = value
    return str(value)


def evaluate(node):
    if isinstance(node, ast.Expression):
        return evaluate(node.body)

    if isinstance(node, ast.Constant):
        if type(node.value) is bool:
            return node.value
        if type(node.value) is int:
            return Fraction(node.value)
        raise ValueError("Unsupported constant")

    if isinstance(node, ast.UnaryOp):
        value = evaluate(node.operand)
        if isinstance(node.op, ast.Not):
            return not value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return value
        raise ValueError("Unsupported unary operator")

    if isinstance(node, ast.BinOp):
        left, right = evaluate(node.left), evaluate(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
        raise ValueError("Unsupported arithmetic operator")

    if isinstance(node, ast.BoolOp):
        # Evaluate every operand to validate the entire expression.
        values = [evaluate(item) for item in node.values]
        if not all(type(value) is bool for value in values):
            raise ValueError("Nonboolean logical operand")
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
        raise ValueError("Unsupported logical operator")

    if isinstance(node, ast.Compare):
        left = evaluate(node.left)
        results = []
        for operator, operand in zip(node.ops, node.comparators):
            right = evaluate(operand)
            if isinstance(operator, ast.Gt):
                results.append(left > right)
            elif isinstance(operator, ast.LtE):
                results.append(left <= right)
            else:
                raise ValueError("Unsupported comparison")
            left = right
        return all(results)

    if isinstance(node, ast.Call):
        if not isinstance(node.func, ast.Name) or node.keywords:
            raise ValueError("Unsupported call")
        values = [evaluate(argument) for argument in node.args]
        if node.func.id == "max":
            return max(values)
        if node.func.id == "min":
            return min(values)
        raise ValueError("Unsupported function")

    raise ValueError("Unsupported syntax")


try:
    results = {}
    for label, expression in expressions.items():
        expression = re.sub(
            r"The capital of ([A-Za-z ]+) is ([A-Za-z ]+)\.",
            substitute_fact,
            expression,
        )
        expression = expression.replace("is greater than", ">")
        expression = expression.replace("is less than or equal to", "<=")
        result = evaluate(ast.parse(expression, mode="eval"))
        if type(result) is not bool:
            raise ValueError("Expression did not produce a boolean")
        results[label] = result

    true_labels = [label for label, value in results.items() if value]
    if len(true_labels) != 1:
        print("UNSUPPORTED")
    else:
        print(json.dumps({
            "final_answer": true_labels[0],
            "evidence": {
                "values": results,
                "capital_claims": fact_values,
                "arithmetic": "exact rational",
            },
        }, separators=(",", ":")))
except Exception:
    print("UNSUPPORTED")
